  if role=='chef':body+='<path d="M28 20V6h41v14z" fill="#fffbed" stroke="#c4c1a6" stroke-width="2"/><path d="M28 9C9 9 14-11 31-8c1-15 24-15 28-1C78-17 88 7 69 12z" fill="#fffbed" stroke="#c4c1a6" stroke-width="2" transform="translate(0 10)"/><path d="M37 71v39h26V71" fill="#ecdebd"/><circle cx="49" cy="81" r="2" fill="#6d6953"/><circle cx="49" cy="92" r="2" fill="#6d6953"/>'
